import 'package:flutter/material.dart';\r\nimport 'package:flutter_test/flutter_test.dart';\r\nimport 'package:stylehub/widgets/data_state_view.dart';\r\nimport 'package:stylehub/core/widgets/app_loading.dart';\r\nimport 'package:stylehub/core/widgets/app_error_widget.dart';\r\n\r\nvoid main() {\r\n  Widget buildTestWidget({required Widget child}) {\r\n    return MaterialApp(\r\n      home: Scaffold(body: child),\r\n    );\r\n  }\r\n\r\n  group('DataStateView Tests', () {\r\n    testWidgets('shows loading state', (tester) async {\r\n      await tester.pumpWidget(buildTestWidget(\r\n        child: DataStateView<String>(\r\n          isLoading: true,\r\n          successBuilder: (data) => Text(data),\r\n        ),\r\n      ));\r\n\r\n      expect(find.byType(AppCircularProgressIndicator), findsOneWidget);\r\n    });\r\n\r\n    testWidgets('shows error state', (tester) async {\r\n      await tester.pumpWidget(buildTestWidget(\r\n        child: DataStateView<String>(\r\n          isLoading: false,\r\n          error: 'Test Error Message',\r\n          successBuilder: (data) => Text(data),\r\n        ),\r\n      ));\r\n\r\n      expect(find.byType(AppErrorWidget), findsOneWidget);\r\n      expect(find.text('Test Error Message'), findsOneWidget);\r\n    });\r\n\r\n    testWidgets('shows empty state when data is null', (tester) async {\r\n      await tester.pumpWidget(buildTestWidget(\r\n        child: DataStateView<String>(\r\n          isLoading: false,\r\n          data: null,\r\n          successBuilder: (data) => Text(data),\r\n        ),\r\n      ));\r\n\r\n      expect(find.text('No data available'), findsOneWidget);\r\n    });\r\n\r\n    testWidgets('shows success state when data is present', (tester) async {\r\n      await tester.pumpWidget(buildTestWidget(\r\n        child: DataStateView<String>(\r\n          isLoading: false,\r\n          data: 'Success Data',\r\n          successBuilder: (data) => Text(data),\r\n        ),\r\n      ));\r\n\r\n      expect(find.text('Success Data'), findsOneWidget);\r\n    });\r\n  });\r\n}\r\n
